CREATE TABLE IF NOT EXISTS strategy_registry(strategy_id TEXT NOT NULL, strategy_version TEXT NOT NULL, parameter_version TEXT NOT NULL, definition_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(strategy_id,strategy_version,parameter_version));
CREATE TABLE IF NOT EXISTS model_registry(model_id TEXT NOT NULL, model_version TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL, hypothesis TEXT, approved_by TEXT, approved_at TEXT, created_at TEXT NOT NULL, PRIMARY KEY(model_id,model_version));
CREATE TABLE IF NOT EXISTS paper_accounts(account_id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL, initial_cash REAL NOT NULL, available_cash REAL NOT NULL, frozen_cash REAL NOT NULL, model_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_orders(order_id TEXT PRIMARY KEY, account_id TEXT NOT NULL, strategy_id TEXT NOT NULL, model_version TEXT NOT NULL, symbol TEXT NOT NULL, side TEXT NOT NULL, order_type TEXT NOT NULL, signal_time TEXT NOT NULL, submit_time TEXT NOT NULL, limit_price REAL, requested_quantity INTEGER NOT NULL, filled_quantity INTEGER NOT NULL, average_fill_price REAL NOT NULL, remaining_quantity INTEGER NOT NULL, commission REAL NOT NULL, tax REAL NOT NULL, slippage REAL NOT NULL, status TEXT NOT NULL, rejection_reason TEXT, data_timestamp TEXT, FOREIGN KEY(account_id) REFERENCES paper_accounts(account_id));
CREATE TABLE IF NOT EXISTS paper_fills(fill_id INTEGER PRIMARY KEY, order_id TEXT NOT NULL, fill_time TEXT NOT NULL, quantity INTEGER NOT NULL, price REAL NOT NULL, commission REAL NOT NULL, tax REAL NOT NULL, slippage_cost REAL NOT NULL, impact_cost REAL NOT NULL, data_timestamp TEXT NOT NULL, FOREIGN KEY(order_id) REFERENCES paper_orders(order_id));
CREATE TABLE IF NOT EXISTS paper_positions(account_id TEXT NOT NULL, symbol TEXT NOT NULL, quantity INTEGER NOT NULL, sellable_quantity INTEGER NOT NULL, pending_t1_quantity INTEGER NOT NULL, average_cost REAL NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(account_id,symbol));
CREATE TABLE IF NOT EXISTS paper_equity(account_id TEXT NOT NULL, trade_date TEXT NOT NULL, available_cash REAL NOT NULL, frozen_cash REAL NOT NULL, market_value REAL NOT NULL, total_equity REAL NOT NULL, realized_pnl REAL NOT NULL, unrealized_pnl REAL NOT NULL, total_costs REAL NOT NULL, industry_exposure_json TEXT NOT NULL, strategy_exposure_json TEXT NOT NULL, PRIMARY KEY(account_id,trade_date));

